<template>
  <section v-if="available || error" class="research-workspace" aria-label="HVG化学计量与功能研究">
    <div class="research-heading"><div><h2>HVG化学计量与功能研究</h2><p>标准标签、全Core差异、功能关联与候选证据</p></div><button class="btn secondary" @click="loadSummary" :disabled="loading">刷新研究状态</button></div>
    <p v-if="error" role="alert">{{ error }} <button @click="loadSummary">重新加载</button></p>
    <template v-if="available">
      <div class="research-toolbar">
        <label>运行版本<select v-model="run"><option v-for="r in runs" :key="r.analysis_run_id" :value="r.analysis_run_id">{{ r.analysis_run_id }} · {{ r.research_status }}</option></select></label>
        <label>分析情境<select v-model="context"><option v-for="c in summary.contexts || []" :key="c.context_id" :value="c.context_id">{{ c.context_id }} · H {{ c.H }} / N {{ c.N }}</option></select></label>
        <span>研究：<strong>{{ summary.status }}</strong> · 模型：{{ summary.model_status || 'pending' }}</span><button class="btn secondary" @click="openModel">查看独立旧模型（global）</button>
      </div>
      <p class="research-caution">统计为基因间关联。重采样属于技术稳定性；特征或集合的q值不是单基因显著性。序列元素计数不代表实际细胞资源消耗。</p>
      <ul v-if="summary.limitations?.length"><li v-for="l in summary.limitations" :key="l">{{ l }}</li></ul>
      <details><summary>运行阶段、耗时与分析状态</summary><div class="research-table"><table><thead><tr><th>阶段</th><th>执行状态</th><th>科学状态</th><th>耗时/秒</th><th>说明</th></tr></thead><tbody><tr v-for="(s,k) in summary.stages" :key="k"><td>{{ k }}</td><td>{{ s.execution_status }}</td><td>{{ s.scientific_status || '待完成' }}</td><td>{{ format(s.seconds) }}</td><td>{{ s.reason }}</td></tr></tbody></table></div></details>
      <nav class="research-nav" aria-label="研究结果栏目"><button v-for="p in panels" :key="p.key" :class="{selected:panel===p.key}" :aria-pressed="panel===p.key" @click="selectPanel(p.key)">{{ p.label }}</button></nav>
      <template v-if="panel==='overview'">
        <h3>设计与覆盖</h3><p>物种：{{ summary.species_id }} · schema：{{ summary.schema_version }}。下表为完整结果数量；没有显著项与尚未计算分别展示。</p>
        <div class="research-table"><table><thead><tr><th>结果类型</th><th>完整记录数</th><th>全局BH显著</th></tr></thead><tbody><tr v-for="(v,k) in summary.tables" :key="k"><td>{{ k }}</td><td>{{ v.rows }}</td><td>{{ v.significant ?? '不适用' }}</td></tr></tbody></table></div>
        <h3>实际基因与Core覆盖</h3><div class="research-table"><table><thead><tr><th>情境</th><th>合格基因</th><th>HVG</th><th>non-HVG</th><th>有功能注释</th><th>注释比例</th><th>Core审计 / 检验</th></tr></thead><tbody><tr v-for="c in summary.coverage || []" :key="c.context_id"><td>{{ c.context_id }}</td><td>{{ c.U }}</td><td>{{ c.H }}</td><td>{{ c.N }}</td><td>{{ c.annotated_genes }}</td><td>{{ (100*c.annotation_fraction).toFixed(2) }}%</td><td>{{ c.audited_core }} / {{ c.tested_core }}</td></tr></tbody></table></div><h3>有证据的观察</h3><p v-if="!phenomena.length">尚无达到预声明门槛的观察，请检查阶段状态和全部特征结果。</p><ul><li v-for="p in phenomena" :key="p.phenomenon_id"><button v-if="p.feature_key" class="research-link" @click="openFeature(p.feature_key)">{{ p.feature_key }}</button><span v-else>{{ p.term_name || p.term_key }}</span><button v-if="p.term_key" class="research-link" @click="openTerm(p.term_key)">{{ p.term_name }}</button>：{{ p.observation }}；效应 {{ format(p.effect) }}；全局q {{ format(p.q_global) }}；{{ p.support_level }}。独立外部验证未完成。</li></ul>
      </template>
      <template v-else-if="panel==='downloads'">
        <h3>完整结果与复现下载</h3><p>下载包含完整成员和非显著结果，不受页面预览数量限制。CSV.gz解压后为CSV；表格软件安全导出会保护公式前缀，原始机器可读文件保留ID。</p>
        <input v-model="artifactQuery" placeholder="筛选文件名或格式" aria-label="筛选下载文件" />
        <div class="research-table"><table><thead><tr><th>文件</th><th>大小</th><th>SHA256</th><th>下载</th></tr></thead><tbody><tr v-for="a in visibleArtifacts" :key="a.artifact_id"><td>{{ a.name }}</td><td>{{ a.bytes }}</td><td class="research-hash">{{ a.sha256 }}</td><td><button class="btn secondary" @click="download(a)">下载文件</button></td></tr></tbody></table></div>
      </template>
      <template v-else>
        <h3>{{ current.label }}</h3><p>{{ current.description }}</p>
        <div class="research-toolbar">
          <label>结果表<select v-model="table"><option v-for="x in current.tables" :key="x[0]" :value="x[0]">{{ x[1] }}</option></select></label>
          <label>搜索<input v-model="query" placeholder="基因、特征或功能名称" @keyup.enter="refreshTable" /></label>
          <label>特征<input v-model="feature" placeholder="如 genome::gc3_percent" /></label>
          <label>功能ID<input v-model="term" placeholder="如 GO_BP::GO:000..." /></label>
          <label>注释来源<select v-model="source"><option value="">全部</option><option v-for="s in ['GO_BP','GO_MF','GO_CC','KEGG_pathway','KEGG_module']" :key="s">{{ s }}</option></select></label>
          <label>方向<select v-model="direction"><option value="">全部</option><option value="high">高方向</option><option value="low">低方向</option></select></label><label>全局q上限<input v-model="qmax" type="number" min="0" max="1" step="0.01" placeholder="全部" /></label>
          <label v-if="panel==='candidates'">优先级<select v-model="tier"><option value="">全部</option><option>A</option><option>B</option><option>C</option><option>D</option></select></label>
          <button class="btn" @click="refreshTable">应用筛选</button><button class="btn secondary" @click="clearFilters">清除筛选</button><button class="btn secondary" @click="exportSafe">导出筛选结果CSV</button>
        </div>
        <p v-if="loading" role="status">正在读取研究结果…</p><p v-if="tableError" role="alert">{{ tableError }} <button @click="loadTable">重试读取</button></p>
        <p>完整匹配 {{ total }} 条，第 {{ page }} / {{ Math.max(1,Math.ceil(total/pageSize)) }} 页。空值表示不可估计或缺失，请查看status/reason字段。</p>
        <EChart v-if="chartOption" :option="chartOption" :data-rows="rows" :auto-loading="false" :height="380" caption="当前筛选页的无量纲效应或富集倍数预览；统计与全局q由完整检验家族计算。" />
        <div class="research-table"><table><thead><tr><th v-for="c in columns" :key="c"><button @click="sortBy(c)" :disabled="!sortable.includes(c)">{{ c }} {{ sort===c ? (order==='asc'?'↑':'↓') : '' }}</button></th><th>证据下钻</th></tr></thead><tbody><tr v-for="(row,i) in rows" :key="`${page}-${i}`"><td v-for="c in columns" :key="c">{{ format(row[c]) }}</td><td><div class="research-actions"><button v-if="row.feature_key" @click="openFeature(row.feature_key)">特征详情</button><button v-if="row.set_id" @click="openSet(row.set_id)">集合成员</button><button v-if="row.term_key" @click="openTerm(row.term_key)">功能内比较</button><button v-if="table==='gsea' && row.run_id" @click="openGsea(row)">GSEA曲线</button><button v-if="row.gene_id" @click="openGene(row.gene_id)">基因证据</button></div></td></tr></tbody></table></div>
        <p v-if="!loading && !rows.length">当前筛选未匹配记录。清除q筛选可查看不可估计行及具体status/reason；研究状态、来源覆盖与阶段状态见概览。</p>
        <div class="research-toolbar"><button class="btn secondary" :disabled="page<=1" @click="page--;loadTable()">上一页</button><button class="btn secondary" :disabled="page*pageSize>=total" @click="page++;loadTable()">下一页</button><label>每页<select v-model.number="pageSize" @change="refreshTable"><option :value="25">25</option><option :value="50">50</option><option :value="100">100</option><option :value="200">200</option></select></label></div>
      </template>
      <section v-if="detail" class="research-detail" aria-live="polite"><div class="research-heading"><h3>{{ detailTitle }}</h3><button class="btn secondary" @click="detail=null">关闭详情</button></div><p>下钻保持当前运行与情境。q值属于对应特征检验或集合功能检验。</p><EChart v-if="gseaCurve" :option="gseaCurve" :auto-loading="false" caption="来自本次保存的真实特征排序与功能成员；曲线显示最多1000个确定性位置，保留峰值。" /><template v-for="(value,key) in detail" :key="key"><template v-if="Array.isArray(value)"><h4>{{ key }}（{{ value.length }}）</h4><div class="research-table"><table v-if="value.length"><thead><tr><th v-for="c in Object.keys(value[0])" :key="c">{{ c }}</th></tr></thead><tbody><tr v-for="(row,i) in value" :key="i"><td v-for="c in Object.keys(value[0])" :key="c">{{ format(row[c]) }}</td></tr></tbody></table><p v-else>本基因/对象没有此类证据。</p></div></template></template></section>
    </template>
  </section>
</template>
<script setup>
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import EChart from '../EChart.vue'
import {researchGet,researchDownload,researchSafeExport} from '../../api/hvgResearch'
const props=defineProps({identifier:{type:String,required:true}}),emit=defineEmits(['available']),route=useRoute(),router=useRouter()
const available=ref(false),error=ref(''),summary=ref({}),runs=ref([]),phenomena=ref([]),artifacts=ref([]),artifactQuery=ref(''),run=ref(String(route.query.research_run||'')),context=ref(String(route.query.research_context||'global')),panel=ref(String(route.query.research_panel||'overview')),feature=ref(String(route.query.research_feature||'')),term=ref(String(route.query.research_term||'')),query=ref(''),source=ref(''),direction=ref(''),tier=ref(''),qmax=ref(''),table=ref('features'),page=ref(1),pageSize=ref(50),total=ref(0),rows=ref([]),sort=ref(''),order=ref('asc'),loading=ref(false),tableError=ref(''),detail=ref(null),detailTitle=ref('')
const sortable=['feature_key','gene_id','gene_name','term_key','term_name','q_global','effect','beta','priority_rank','hvg_score','n_members','source','final_status','omics','family','status','nes','fold_enrichment','context_id','priority_tier','n1','n0','rank','hvg_rank','direction']
const panels=[
{key:'overview',label:'研究概览',tables:[]},
{key:'features',label:'全Core特征',description:'全部合法Core的审计、原始差异、协变量校正与匹配敏感性。大数值和小数值分列处理。',tables:[['features','特征证据汇总'],['core_audit','全部Core审计'],['adjusted','校正模型'],['matching','匹配诊断'],['categorical_tests','分类特征']]},
{key:'sets',label:'方向基因集',description:'高低方向参考non-HVG的冻结分位；调整集合使用不含HVG标签的特征残差。',tables:[['sets','原始方向集合'],['set_members','集合成员'],['gene_features','选择证据'],['adjusted_sets','调整方向集合'],['joint_sets','家族联合集合']]},
{key:'enrichment',label:'富集对照',description:'区分原始、同背景、特征子集与HVG内条件检验；不以两个q的大小判断富集增强。',tables:[['baseline','原始HVG'],['matched_baseline','同背景HVG'],['subset','特征方向子集'],['within_hvg','HVG内条件富集'],['enrichment_comparison','同背景对照'],['supplementary_ora','调整及联合集合']]},
{key:'pathways',label:'特征与功能',description:'连续特征关系、真实特征rank GSEA及独立交互检验。GO定位、功能和KEGG通路分别解释。',tables:[['feature_pathways','连续关系'],['gsea','真实GSEA'],['gsea_runs','GSEA适用性'],['interactions','交互模型'],['leading_edge','Leading edge成员'],['ranked_genes','完整特征排名']]},
{key:'within',label:'功能内部比较',description:'仅比较同一功能类别内的HVG与non-HVG；不足样本不会借用类别外基因。',tables:[['within_pathways','原始比较'],['within_adjusted','功能内校正']]},
{key:'stability',label:'稳定性',description:'参数、细胞重采样与声明供体敏感性。技术稳定性不等于外部生物学复现。',tables:[['replication','官方HVG重新计算'],['feature_stability','特征方向稳定性'],['candidate_stability','基因入选频率'],['set_stability','集合稳定性']]},
{key:'candidates',label:'候选与单基因',description:'全部候选可分页，未注释的强特征候选保留。优先级是后续验证线索。',tables:[['candidates','候选基因'],['candidate_evidence','候选证据'],['gene_pathways','候选功能关系'],['labels','全部标准标签'],['annotations','实际功能注释']]},
{key:'downloads',label:'完整下载',tables:[]}]
const current=computed(()=>panels.find(p=>p.key===panel.value)||panels[0]),visibleArtifacts=computed(()=>artifacts.value.filter(a=>(a.name+' '+a.format).toLowerCase().includes(artifactQuery.value.toLowerCase())))
const columns=computed(()=>{const present=new Set(rows.value.flatMap(Object.keys));const first=['gene_id','gene_name','feature_key','term_key','term_name','direction','scope','source','priority_tier','priority_rank','final_status','status','n_hvg','n_nonhvg','n1','n0','N','K','n','k','effect','ci_low','ci_high','beta','odds_ratio','nes','fold_enrichment','p_value','q_global','adjusted_q','strong_raw','n_members','threshold','set_id','reason'];return first.filter(c=>present.has(c)).concat([...present].filter(c=>!first.includes(c)))})
const params=()=>({analysis_run_id:run.value||undefined,context_id:context.value||undefined,set_id:table.value==='set_members'?(setFilter.value||undefined):undefined,feature_key:feature.value||undefined,term_key:term.value||undefined,source:source.value||undefined,direction:direction.value||undefined,priority_tier:tier.value||undefined,q_max:qmax.value,query:query.value,page:page.value,page_size:pageSize.value,sort:sort.value||undefined,order:order.value})
const format=v=>v===null||v===undefined?'—':typeof v==='number'?(Math.abs(v)>0&&Math.abs(v)<.001?v.toExponential(3):Number(v.toPrecision(6)).toString()):typeof v==='object'?JSON.stringify(v):String(v)
function persist(){router.replace({query:{...route.query,research_run:run.value,research_context:context.value,research_panel:panel.value,research_feature:feature.value||undefined,research_term:term.value||undefined}})}
let generation=0,tableGeneration=0,timer
async function loadSummary(){const id=++generation;error.value='';try{const [s,r]=await Promise.all([researchGet(props.identifier,'summary',params()),researchGet(props.identifier,'runs')]);if(id!==generation)return;summary.value=s;runs.value=r.rows||[];available.value=true;emit('available',true);if(!run.value)run.value=s.analysis_run_id;const p=await researchGet(props.identifier,'phenomena',params());phenomena.value=p.rows||[];if(s.status==='running')timer=setTimeout(loadSummary,5000)}catch(e){if(e.response?.status===404){available.value=false;return}error.value=e.response?.data?.error?.message||e.message}}
async function loadTable(){const id=++tableGeneration;loading.value=true;tableError.value='';try{const r=await researchGet(props.identifier,`table/${table.value}`,params());if(id!==tableGeneration)return;rows.value=r.rows||[];total.value=r.total||0;persist()}catch(e){tableError.value=e.response?.data?.error?.message||e.message}finally{if(id===tableGeneration)loading.value=false}}
async function selectPanel(k){panel.value=k;detail.value=null;sort.value='';query.value='';page.value=1;table.value=(panels.find(p=>p.key===k)?.tables||[])[0]?.[0]||'';persist();if(k==='downloads'){const a=await researchGet(props.identifier,'artifacts',params());artifacts.value=a.rows||[]}else if(k!=='overview')await loadTable()}
function refreshTable(){page.value=1;loadTable()}
function clearFilters(){setFilter.value='';feature.value='';term.value='';source.value='';direction.value='';qmax.value='';query.value='';tier.value='';refreshTable()}
function sortBy(c){sort.value=c;order.value=order.value==='asc'?'desc':'asc';refreshTable()}
async function openFeature(k){gseaCurve.value=null;feature.value=k;detailTitle.value=k;try{detail.value=await researchGet(props.identifier,`features/${encodeURIComponent(k)}`,params());persist()}catch(e){tableError.value=e.message}}
async function openSet(id){gseaCurve.value=null;try{const r=await researchGet(props.identifier,`gene-sets/${encodeURIComponent(id)}`,params());detailTitle.value=id;detail.value={definition:r.definition.rows,members:r.members.rows};panel.value='sets';table.value='set_members';query.value='';feature.value='';setFilter.value=id;refreshTable()}catch(e){tableError.value=e.message}}
const gseaCurve=ref(null)
async function openModel(){gseaCurve.value=null;try{detailTitle.value='独立旧模型（global）';detail.value=await researchGet(props.identifier,'optional-model',params())}catch(e){tableError.value=e.message}}
async function openGsea(row){try{const p=await researchGet(props.identifier,'plots/gsea_curve',{...params(),run_id:row.run_id,term_key:row.term_key});detailTitle.value='GSEA: '+row.term_name;detail.value={test:[row]};gseaCurve.value={tooltip:{trigger:'axis'},xAxis:{type:'value',name:'Gene rank'},yAxis:{type:'value',name:'Running ES'},series:[{type:'line',showSymbol:false,data:p.rows.map(x=>[x.rank,x.running_es])}]}}catch(e){tableError.value=e.message}}
const setFilter=ref('');const originalParams=params
// Set membership uses the same paginated endpoint, with no preview cap on downloadable members.
async function openTerm(t){term.value=t;await selectPanel('within');refreshTable()}
async function openGene(g){gseaCurve.value=null;try{detailTitle.value=g;detail.value=await researchGet(props.identifier,`genes/${encodeURIComponent(g)}`,params());persist()}catch(e){tableError.value=e.message}}
async function download(a){try{await researchDownload(props.identifier,a,params())}catch(e){error.value=e.message}}
async function exportSafe(){try{await researchSafeExport(props.identifier,table.value,params())}catch(e){tableError.value=e.message}}
const chartOption=computed(()=>{if(table.value==='feature_pathways'&&rows.value.length){const v=rows.value.filter(r=>Number.isFinite(r.effect)),fx=[...new Set(v.map(r=>r.feature_key))],ty=[...new Set(v.map(r=>r.term_name))];return {tooltip:{},grid:{left:230,bottom:100,top:30},xAxis:{type:'category',data:fx,axisLabel:{rotate:60,width:100,overflow:'truncate'}},yAxis:{type:'category',data:ty,axisLabel:{width:220,overflow:'truncate'}},visualMap:{min:-1,max:1,orient:'horizontal',left:'center',top:0,inRange:{color:['#ad6649','#f5f6f7','#286488']}},series:[{type:'heatmap',data:v.map(r=>[fx.indexOf(r.feature_key),ty.indexOf(r.term_name),r.effect])}]}}const f=rows.value.filter(r=>Number.isFinite(r.effect??r.nes??r.fold_enrichment)).slice(0,25);if(!f.length)return null;return {tooltip:{trigger:'axis'},grid:{left:220,right:25,bottom:55,top:15},xAxis:{type:'value',name:'效应 / NES / 富集倍数'},yAxis:{type:'category',data:f.map(r=>r.feature_key||r.term_name||r.gene_id),axisLabel:{width:205,overflow:'truncate'}},series:[{type:'bar',data:f.map(r=>r.effect??r.nes??r.fold_enrichment),itemStyle:{color:'#286488'}}]}})
watch(table,()=>{if(table.value&&available.value){refreshTable()}})
watch([run,context],async()=>{detail.value=null;rows.value=[];page.value=1;persist();await loadSummary();if(!['overview','downloads'].includes(panel.value))loadTable()})
onMounted(async()=>{await loadSummary();if(available.value&&panel.value!=='overview')selectPanel(panel.value)})
onBeforeUnmount(()=>{generation++;clearTimeout(timer)})
</script>
<style scoped>
.research-workspace{margin:24px 0;padding:24px;background:var(--surface,#fff);border:1px solid var(--line-soft,#cdd7de);border-radius:10px;color:var(--text,#243746)}
.research-heading,.research-toolbar{display:flex;gap:16px;align-items:center;justify-content:space-between;flex-wrap:wrap}.research-heading h2{font-size:1.5rem;margin:0}.research-heading p{margin:8px 0 16px}.research-toolbar{justify-content:flex-start;margin:16px 0;align-items:end}.research-toolbar label{display:flex;flex-direction:column;gap:6px;font-size:.9rem}.research-toolbar input,.research-toolbar select{max-width:260px;min-height:36px;border:1px solid #9baeba;border-radius:5px;padding:5px;color:#243746;background:#fff}.research-caution{max-width:75ch;font-size:.9rem;line-height:1.6;background:#edf3f7;padding:12px;border-radius:6px}.research-nav{display:flex;gap:6px;flex-wrap:wrap;border-bottom:1px solid #b8c7d2;padding:12px 0;margin-bottom:20px}.research-nav button{border:0;background:transparent;padding:10px 12px;color:#29495e;border-radius:4px;cursor:pointer}.research-nav button.selected{background:#205d80;color:white}.research-table{overflow:auto;max-height:620px;margin:14px 0}.research-table table{border-collapse:collapse;min-width:100%;font-size:.85rem}.research-table th,.research-table td{border-bottom:1px solid #d8e0e6;text-align:left;vertical-align:top;padding:9px 11px;max-width:330px;overflow-wrap:anywhere}.research-table th{background:#edf3f7;position:sticky;top:0;white-space:nowrap}.research-table th button{border:0;background:none;color:inherit;font:inherit}.research-actions{display:flex;gap:6px;flex-wrap:wrap;min-width:160px}.research-actions button,.research-link{border:0;background:none;color:#135f8c;text-decoration:underline;cursor:pointer}.research-hash{font:11px monospace}.research-detail{margin-top:24px;padding-top:20px;border-top:1px solid #abbfcd}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid #205d80;outline-offset:3px}button:disabled{opacity:.55;cursor:default}@media(max-width:760px){.research-workspace{padding:14px}.research-toolbar label{width:100%}.research-toolbar input,.research-toolbar select{max-width:100%;width:100%}.research-table{max-height:480px}}
</style>
